using System.Collections;
using System.Collections.Generic;
using System.Runtime.CompilerServices;
using bhl;

namespace UnityBHL
{

//NOTE: the value conversions of the bindings generated by bindgen which do more than reading a field of a Val:
//      To* reads a Val, Pop* pops and releases it. A plain value is read by the generated code itself,
//      a call is a real one in the editor (Unity compiles it without -optimize)
public static class BindConv
{
  //NOTE: the Origin of every generated symbol in a player: its C# declaration only matters to the BHL front (the
  //      LSP's go to definition) and the editor; ("", 0) as new Origin() would keep this file's path
  public static readonly Origin NoOrigin = new Origin("", 0);

  //NOTE: the result keeps a reference of its own
  [MethodImpl(MethodImplOptions.AggressiveInlining)]
  public static Val ToAny(in Val v)
  {
    var res = v;
    res._refc?.Retain();
    return res;
  }

  //NOTE: the result keeps a reference of its own
  [MethodImpl(MethodImplOptions.AggressiveInlining)]
  public static VM.FuncPtr ToFunc(in Val v)
  {
    var res = (VM.FuncPtr)v.obj;
    res.Retain();
    return res;
  }

  //NOTE: a BHL array is wrapped, a native list is passed as is; the result keeps a reference of the array,
  //      the wrapper knows the array's type to go back as it (NativeListTypeSymbol<T>.SetList)
  [MethodImpl(MethodImplOptions.AggressiveInlining)]
  public static IList<T> ToList<T>(in Val v, NativeListTypeSymbol<T> proxy)
  {
    IList<T> res;
    if(v.obj is ValList vl)
      res = ValList<T>.New(vl, proxy.Val2Native, v.type);
    else
      res = (IList<T>)v.obj;
    v._refc?.Retain();
    return res;
  }

  //NOTE: the result keeps a reference of the array
  [MethodImpl(MethodImplOptions.AggressiveInlining)]
  public static IList ToAnyList(in Val v)
  {
    var res = (IList)v.obj;
    v._refc?.Retain();
    return res;
  }

  [MethodImpl(MethodImplOptions.AggressiveInlining)]
  public static Val PopAny(VM.ExecState exec)
  {
    var dv = exec.stack.Pop();
    var res = ToAny(dv);
    dv._refc?.Release();
    return res;
  }

  [MethodImpl(MethodImplOptions.AggressiveInlining)]
  public static VM.FuncPtr PopFunc(VM.ExecState exec)
  {
    var dv = exec.stack.Pop();
    var res = ToFunc(dv);
    dv._refc?.Release();
    return res;
  }

  [MethodImpl(MethodImplOptions.AggressiveInlining)]
  public static IList<T> PopList<T>(VM.ExecState exec, NativeListTypeSymbol<T> proxy)
  {
    var dv = exec.stack.Pop();
    var res = ToList<T>(dv, proxy);
    dv._refc?.Release();
    return res;
  }

  [MethodImpl(MethodImplOptions.AggressiveInlining)]
  public static IList PopAnyList(VM.ExecState exec)
  {
    var dv = exec.stack.Pop();
    var res = ToAnyList(dv);
    dv._refc?.Release();
    return res;
  }
}

}
